<?php
/** Testimonials block. */
$eyebrow=get_field('eyebrow'); $title=get_field('title'); $description=get_field('description'); $items=get_field('testimonials');
?><section class="sariyah-testimonials"><div class="sariyah-container"><div class="sariyah-testimonials__heading"><?php if($eyebrow): ?><p class="sariyah-section-eyebrow"><?php echo esc_html($eyebrow); ?></p><?php endif; ?><?php if($title): ?><h2><?php echo esc_html($title); ?></h2><?php endif; ?><?php if($description): ?><p><?php echo esc_html($description); ?></p><?php endif; ?></div><?php if(is_array($items)&&$items): ?><div class="sariyah-testimonials__grid"><?php foreach($items as $item): ?><article class="sariyah-testimonial"><div class="sariyah-testimonial__quote">“<?php echo esc_html($item['quote']??''); ?>”</div><div class="sariyah-testimonial__person"><?php $image=$item['image']??null; if(is_array($image)&&!empty($image['ID'])) echo wp_get_attachment_image((int)$image['ID'],'thumbnail',false,array('loading'=>'lazy')); ?><div><strong><?php echo esc_html($item['name']??''); ?></strong><span><?php echo esc_html($item['role']??''); ?></span></div></div></article><?php endforeach; ?></div><?php endif; ?></div></section>